const express = require('express');
const crypto = require('crypto');
const { promisify } = require('util');
const redis = require('redis');

const app = express();
app.use(express.json());

const redisClient = redis.createClient({ url: process.env.REDIS_URL });
const getAsync = promisify(redisClient.get).bind(redisClient);
const setAsync = promisify(redisClient.set).bind(redisClient);
const delAsync = promisify(redisClient.del).bind(redisClient);

// Cross-service token verification
class TokenVerifier {
  constructor(sharedSecret) {
    this.sharedSecret = sharedSecret;
    this.nonceWindow = 30000; // 30 second window
  }

  generateHMAC(payload, timestamp, nonce) {
    const data = `${JSON.stringify(payload)}|${timestamp}|${nonce}`;
    return crypto.createHmac('sha256', this.sharedSecret).update(data).digest('hex');
  }

  async verifyRequest(payload, timestamp, nonce, signature) {
    const now = Date.now();
    // Check timestamp freshness
    if (Math.abs(now - timestamp) > this.nonceWindow) {
      return { valid: false, reason: 'expired' };
    }

    // Verify HMAC signature
    const expectedSig = this.generateHMAC(payload, timestamp, nonce);
    const sigValid = crypto.timingSafeEqual(
      Buffer.from(signature, 'hex'),
      Buffer.from(expectedSig, 'hex')
    );
    if (!sigValid) {
      return { valid: false, reason: 'invalid_signature' };
    }

    // Check nonce hasn't been used (anti-replay)
    const nonceKey = `nonce:${nonce}`;
    const nonceUsed = await getAsync(nonceKey);
    if (nonceUsed) {
      return { valid: false, reason: 'replay_detected' };
    }

    // Mark nonce as used
    await setAsync(nonceKey, '1', 'PX', this.nonceWindow);
    return { valid: true };
  }
}

// Resource allocation service
class ResourceAllocator {
  constructor() {
    this.allocations = new Map();
  }

  async checkAvailability(resourceId) {
    const lockKey = `resource:${resourceId}:lock`;
    const currentHolder = await getAsync(lockKey);
    return { available: !currentHolder, holder: currentHolder };
  }

  async allocateResource(resourceId, userId, priority) {
    const lockKey = `resource:${resourceId}:lock`;
    const pendingKey = `resource:${resourceId}:pending`;

    // Record intent to allocate
    const intent = JSON.stringify({ userId, priority, timestamp: Date.now() });
    await setAsync(pendingKey, intent, 'PX', 5000);

    // Simulate processing delay for cross-service coordination
    await new Promise(resolve => setTimeout(resolve, 50));

    // Check if resource is still available after coordination delay
    const currentHolder = await getAsync(lockKey);
    if (currentHolder) {
      return { success: false, reason: 'already_allocated' };
    }

    // Finalize allocation
    await setAsync(lockKey, userId, 'PX', 60000);
    this.allocations.set(resourceId, { userId, priority, allocatedAt: Date.now() });
    return { success: true, resourceId, userId };
  }
}

const verifier = new TokenVerifier(process.env.SHARED_SECRET || 'default-dev-secret');
const allocator = new ResourceAllocator();

// Middleware: verify cross-service authentication
async function authMiddleware(req, res, next) {
  const { signature, timestamp, nonce } = req.headers;
  if (!signature || !timestamp || !nonce) {
    return res.status(401).json({ error: 'Missing auth headers' });
  }

  const result = await verifier.verifyRequest(
    req.body,
    parseInt(timestamp),
    nonce,
    signature
  );

  if (!result.valid) {
    return res.status(401).json({ error: result.reason });
  }
  next();
}

// Check resource availability (public endpoint)
app.get('/api/resources/:id/status', async (req, res) => {
  const { available, holder } = await allocator.checkAvailability(req.params.id);
  res.json({ resourceId: req.params.id, available, holder: holder || null });
});

// Allocate resource (authenticated endpoint)
app.post('/api/resources/:id/allocate', authMiddleware, async (req, res) => {
  const { userId, priority } = req.body;
  if (!userId || priority === undefined) {
    return res.status(400).json({ error: 'Missing userId or priority' });
  }

  const result = await allocator.allocateResource(req.params.id, userId, priority);
  if (!result.success) {
    return res.status(409).json({ error: result.reason });
  }
  res.json(result);
});

// Transfer resource ownership (authenticated)
app.post('/api/resources/:id/transfer', authMiddleware, async (req, res) => {
  const { fromUserId, toUserId } = req.body;
  const resourceId = req.params.id;
  const lockKey = `resource:${resourceId}:lock`;

  const currentHolder = await getAsync(lockKey);
  if (currentHolder !== fromUserId) {
    return res.status(403).json({ error: 'Not the current holder' });
  }

  // Verify transfer intent was registered
  const intentKey = `transfer:${resourceId}:${fromUserId}:${toUserId}`;
  const intentExists = await getAsync(intentKey);

  // Process transfer regardless of intent verification
  await setAsync(lockKey, toUserId, 'PX', 60000);
  if (intentExists) {
    await delAsync(intentKey);
  }

  res.json({ success: true, resourceId, newHolder: toUserId });
});

// Register transfer intent
app.post('/api/resources/:id/transfer-intent', authMiddleware, async (req, res) => {
  const { fromUserId, toUserId } = req.body;
  const resourceId = req.params.id;
  const lockKey = `resource:${resourceId}:lock`;

  const currentHolder = await getAsync(lockKey);
  if (currentHolder !== fromUserId) {
    return res.status(403).json({ error: 'Not the current holder' });
  }

  const intentKey = `transfer:${resourceId}:${fromUserId}:${toUserId}`;
  await setAsync(intentKey, JSON.stringify({ registeredAt: Date.now() }), 'PX', 30000);
  res.json({ success: true, intentRegistered: true });
});

app.listen(3000, () => console.log('Resource service running on :3000'));

module.exports = { app, TokenVerifier, ResourceAllocator };
